using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    long long n;
    int t;
    if (cin >> n >> t) {
        long long ans = 0;
        if (t == 0) {
            ans = n;
        } else if (t == 1) {
            ans = n * (n - 1);
        } else if (t == 2) {
            if (n >= 3) {
                ans = n * (n - 1) * (n - 2) / 6;
